@push('scripts')
<script>
const cart=new Map(), rupiah=n=>'Rp '+Number(n).toLocaleString('id-ID');
function render(){let sub=0, html='';cart.forEach((x,id)=>{sub+=x.price*x.qty;html+=`<div class="border rounded-3 p-2 mb-2"><div class="d-flex justify-content-between"><strong>${x.name}</strong><button type="button" class="btn-close remove" data-id="${id}"></button></div><div class="d-flex align-items-center gap-2 mt-2"><button type="button" class="btn btn-sm btn-outline-secondary minus" data-id="${id}">−</button><span>${x.qty}</span><button type="button" class="btn btn-sm btn-outline-secondary plus" data-id="${id}">+</button><span class="ms-auto fw-semibold">${rupiah(x.price*x.qty)}</span></div><input type="hidden" name="items[${id}][product_id]" value="${id}"><input type="hidden" name="items[${id}][qty]" value="${x.qty}"><input class="form-control form-control-sm mt-2" name="items[${id}][note]" maxlength="200" placeholder="Catatan (opsional)"> </div>`});document.getElementById('cartLines').innerHTML=html;document.getElementById('cartEmpty').style.display=cart.size?'none':'block';let disc=Math.min(Math.max(0,Number(document.getElementById('discount').value)||0),sub),tax=Math.round((sub-disc)*.1),total=sub-disc+tax,paid=Number(document.getElementById('paid').value)||0;document.getElementById('subtotalText').textContent=rupiah(sub);document.getElementById('taxText').textContent=rupiah(tax);document.getElementById('grandText').textContent=rupiah(total);document.getElementById('changeText').textContent=rupiah(Math.max(0,paid-total));document.getElementById('submitBtn').disabled=!cart.size;}
document.querySelectorAll('.add-product').forEach(b=>b.addEventListener('click',()=>{let id=b.dataset.id,x=cart.get(id)||{name:b.dataset.name,price:+b.dataset.price,qty:0,stock:+b.dataset.stock};if(x.qty>=x.stock){alert('Jumlah melebihi stok tersedia.');return}x.qty++;cart.set(id,x);render()}));
document.getElementById('cartLines').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let id=b.dataset.id,x=cart.get(id);if(b.classList.contains('remove'))cart.delete(id);if(b.classList.contains('minus')){x.qty--;if(x.qty<=0)cart.delete(id)}if(b.classList.contains('plus')){if(x.qty>=x.stock){alert('Stok maksimal tercapai');return}x.qty++}render()});
document.getElementById('discount').addEventListener('input',render);document.getElementById('paid').addEventListener('input',render);
document.getElementById('orderType').addEventListener('change',e=>{let dine=e.target.value==='dine_in';document.getElementById('tableWrap').style.display=dine?'':'none';document.getElementById('tableNo').required=dine;});
document.getElementById('searchMenu').addEventListener('input',e=>document.querySelectorAll('.menu-item').forEach(el=>el.style.display=el.dataset.name.includes(e.target.value.toLowerCase())?'':'none'));
document.getElementById('method').addEventListener('change',()=>{if(document.getElementById('method').value!=='cash'){let t=Number(document.getElementById('grandText').textContent.replace(/\D/g,''));document.getElementById('paid').value=t;render()}});
document.getElementById('posForm').addEventListener('submit',e=>{if(!cart.size){e.preventDefault();alert('Keranjang masih kosong.');return}if(document.getElementById('orderType').value==='dine_in'&&!document.getElementById('tableNo').value.trim()){e.preventDefault();alert('Nomor meja wajib diisi.')}});
render();
</script>
@endpush
